window.receiveProjectSource({"path": "test/unit/microservices/event_synthesis/services/test_qa_report_render.py", "lines": ["\"\"\"DAT-8141: HTML rendering, escaping, and the grader-prompt guard.\"\"\"", "", "from __future__ import annotations", "", "import json", "import re", "from datetime import UTC, date, datetime", "from uuid import UUID", "", "import pytest", "from pydantic import ValidationError", "", "from microservices.event_synthesis.repositories.qa_sample import (", "    LinkageCoverageBucket,", "    QASampleDoc,", "    QASampleRow,", ")", "from microservices.event_synthesis.services.qa_report_llm import QAReportGraderClient", "from microservices.event_synthesis.services.qa_report_render import (", "    ALL_ENTITIES_REMOVED,", "    ENTITY_CAUSE_LABELS,", "    FLAG_REASON_LABELS,", "    LINKAGE_IMPLAUSIBLE,", "    LINKAGE_NOT_APPLICABLE,", "    LINKAGE_PLAUSIBLE,", "    NO_ENTITY_LINKS,", "    NOT_MEASURED,", "    TRUNCATION_MARK,", "    UNTITLED,", "    is_flagged,", "    render_report_html,", ")", "from microservices.event_synthesis.services.qa_report_types import (", "    PreparedQAReportInput,", "    QADuplicatePair,", "    QAEventGrade,", "    QAReportDocument,", "    QAReportEntityView,", "    QAReportEventContext,", "    QAReportMetadata,", "    QAReportOutput,", ")", "", "pytestmark = pytest.mark.unit", "", "RUN_AT = datetime(2026, 9, 6, 16, 0, 13, tzinfo=UTC)", "E1 = UUID(\"11111111-1111-4111-8111-111111111111\")", "E2 = UUID(\"22222222-2222-4222-8222-222222222222\")", "E3 = UUID(\"33333333-3333-4333-8333-333333333333\")", "", "", "def _row(event_id: UUID, summary: str = \"A summary.\", n_docs: int = 1) -> QASampleRow:", "    return QASampleRow(", "        event_id=event_id,", "        first_detected_on=RUN_AT,", "        event_class=\"create\" if n_docs < 2 else \"merge\",", "        summary=summary,", "        key_details=\"{}\",", "        docs=[", "            QASampleDoc(document_id=i, source_tier=3, article_type=\"news\", title=f\"Doc {i}\")", "            for i in range(n_docs)", "        ],", "    )", "", "", "def _ctx(", "    event_id: UUID,", "    title: str | None = \"A title\",", "    summary: str = \"A summary.\",", "    included: int = 1,", "    linked_document_count: int = 1,", "    direct_link_count: int = 2,", "    entity_loss_state: str = \"no_loss\",", "    entity_check_status: str = \"complete\",", "    entity_loss_causes: list[str] | None = None,", "    entities: list[QAReportEntityView] | None = None,", ") -> QAReportEventContext:", "    return QAReportEventContext(", "        event_id=event_id,", "        title=title,", "        summary=summary,", "        event_class=\"create\",", "        first_detected_on=RUN_AT,", "        included_doc_count=included,", "        linked_document_count=linked_document_count,", "        direct_link_count=direct_link_count,", "        entity_loss_state=entity_loss_state,  # type: ignore[arg-type]", "        entity_check_status=entity_check_status,  # type: ignore[arg-type]", "        entity_loss_causes=entity_loss_causes or [],  # type: ignore[arg-type]", "        entities=entities if entities is not None else [_entity_view()],", "    )", "", "", "def _entity_view(", "    name: str = \"Acme Corporation\",", "    kind: str = \"CVW\",", "    *,", "    role: str | None = \"subject\",", "    name_truncated: bool = False,", ") -> QAReportEntityView:", "    return QAReportEntityView(", "        entity_id=UUID(\"44444444-4444-4444-8444-444444444444\"),", "        role=role,", "        display_name=name,", "        entity_type=kind,", "        name_truncated=name_truncated,", "    )", "", "", "def _metadata(**over) -> QAReportMetadata:", "    base = dict(", "        run_at=RUN_AT,", "        run_id=\"test1234\",", "        sample_size=40,", "        sampled_count=1,", "        create_count=1,", "        merge_count=0,", "        gradable_merge_count=0,", "        flagged_count=0,", "        duplicate_pair_count=0,", "        truncated_fields=0,", "        dropped_events=0,", "        chat_model=\"gpt-6.1-sol\",", "        fallback_used=False,", "        rotation_enabled=False,", "        out_of_sample_count=0,", "    )", "    base.update(over)", "    return QAReportMetadata(**base)", "", "", "def _doc(events, grades=None, pairs=None, **meta) -> QAReportDocument:", "    return QAReportDocument(", "        metadata=_metadata(sampled_count=len(events), **meta),", "        sampled_event_ids=[e.event_id for e in events],", "        llm_report=QAReportOutput(per_event=grades or [], duplicate_pairs=pairs or []),", "        events=events,", "    )", "", "", "# --------------------------------------------------------------------------- #", "# The guard: this ticket must not move the grader prompt.", "# --------------------------------------------------------------------------- #", "", "", "def test_grader_prompt_is_byte_identical_after_dat_8141():", "    \"\"\"The serialized grader input must not change.", "", "    ``_serialize`` dumps the WHOLE PreparedQAReportInput, so any display field that", "    leaked onto QASampleRow would land in the LLM prompt, consume the input budget,", "    and silently move DAT-7639's acceptance baseline. This golden string is what", "    makes that failure loud instead of invisible.", "    \"\"\"", "    prepared = PreparedQAReportInput(events=[_row(E1)], dropped_event_ids=[], truncated_fields=0)", "    serialized = QAReportGraderClient._serialize(prepared)", "", "    expected = (", "        '{\"dropped_event_ids\": [], \"events\": [{\"changes\": [], '", "        '\"docs\": [{\"article_type\": \"news\", \"document_id\": 0, \"source_tier\": 3, '", "        '\"title\": \"Doc 0\"}], \"entities\": [], \"event_class\": \"create\", '", "        '\"event_id\": \"11111111-1111-4111-8111-111111111111\", '", "        '\"first_detected_on\": \"2026-09-06T16:00:13Z\", \"key_details\": \"{}\", '", "        '\"summary\": \"A summary.\"}], \"truncated_fields\": 0}'", "    )", "    assert serialized == expected, (", "        \"The grader prompt changed. If a display-only field was added to QASampleRow, \"", "        \"move it to the QASampleResult side channel instead (see DAT-8141 plan \u00a72).\"", "    )", "", "", "def test_display_fields_are_absent_from_the_grader_row():", "    \"\"\"Display-only fields must never be addressable on the prompt model.", "", "    Both names are asserted deliberately. ``linked_document_count`` is what the", "    display side channel calls the count today; ``article_count`` is what it was", "    called before, and is still the name of the SourceEvent counter someone might", "    reach for. Either one landing on QASampleRow would enter the grader prompt.", "    \"\"\"", "    assert \"title\" not in QASampleRow.model_fields", "    assert \"linked_document_count\" not in QASampleRow.model_fields", "    assert \"article_count\" not in QASampleRow.model_fields", "", "", "# --------------------------------------------------------------------------- #", "# Escaping. The fixture is built directly as a document -- NEVER by seeding a", "# DAT-7639 sentinel, whose summary is part of the grader prompt.", "# --------------------------------------------------------------------------- #", "", "", "def test_script_payload_in_title_is_escaped():", "    payload = '<script>alert(\"xss\")</script>'", "    html = render_report_html(_doc([_ctx(E1, title=payload)]))", "    assert \"<script>alert\" not in html", "    assert \"&lt;script&gt;\" in html", "", "", "def test_script_payload_in_llm_explanation_is_escaped():", "    \"\"\"`explanation` is free-form model output over scraped text: untrusted.\"\"\"", "    grade = QAEventGrade(", "        event_id=E1,", "        event_valid=False,", "        merge_correct=None,", "        issues=['<img src=x onerror=\"alert(1)\">'],", "        explanation=\"<script>steal()</script>\",", "        confidence=0.9,", "        entity_linkage_plausible=True,", "        entity_linkage_explanation=None,", "    )", "    html = render_report_html(_doc([_ctx(E1)], grades=[grade], flagged_count=1))", "    # Escaping is proven by the markup-forming characters being encoded: with \"<\"", "    # rendered as \"&lt;\" the payload is inert text, so asserting on the substring", "    # \"onerror=\" alone would be a false alarm -- it survives as visible text by", "    # design. What must never appear is a real tag.", "    assert \"<script>steal\" not in html", "    assert \"<img\" not in html", "    assert \"&lt;script&gt;steal()&lt;/script&gt;\" in html", "    assert \"&lt;img src=x onerror=\" in html", "", "", "def test_quote_payload_in_summary_is_escaped():", "    html = render_report_html(_doc([_ctx(E1, summary='\" onmouseover=\"alert(1)')]))", "    assert ' onmouseover=\"alert(1)' not in html", "", "", "# --------------------------------------------------------------------------- #", "# Null title.", "# --------------------------------------------------------------------------- #", "", "", "def test_null_title_renders_fallback_and_stays_null_in_json():", "    document = _doc([_ctx(E1, title=None)])", "    html = render_report_html(document)", "    assert UNTITLED in html", "    # The machine-readable form must stay honest about what the database holds.", "    assert json.loads(document.model_dump_json())[\"events\"][0][\"title\"] is None", "", "", "# --------------------------------------------------------------------------- #", "# Evidence-coverage honesty.", "# --------------------------------------------------------------------------- #", "", "", "def test_partial_evidence_is_surfaced_when_docs_were_capped():", "    html = render_report_html(_doc([_ctx(E1, included=2, linked_document_count=7)]))", "    assert \"Partial evidence\" in html", "    assert \"2 of 7\" in html", "    # No grade on this card, so there is no verdict for the subset to qualify. The", "    # notice must not claim one -- it sits OUTSIDE the grade guard, so the sentence", "    # carries its own.", "    assert \"Any merge verdict above\" not in html", "", "", "def test_no_partial_notice_when_all_documents_were_seen():", "    assert \"Partial evidence\" not in render_report_html(", "        _doc([_ctx(E1, included=3, linked_document_count=3)])", "    )", "", "", "# --------------------------------------------------------------------------- #", "# Section routing.", "# --------------------------------------------------------------------------- #", "", "", "def test_flagged_event_appears_in_the_flagged_section_not_collapsed():", "    bad = QAEventGrade(", "        event_id=E1,", "        event_valid=True,", "        merge_correct=False,", "        issues=[],", "        explanation=\"Two different events on one row.\",", "        confidence=0.9,", "        entity_linkage_plausible=True,", "        entity_linkage_explanation=None,", "    )", "    good = QAEventGrade(", "        event_id=E2,", "        event_valid=True,", "        merge_correct=True,", "        issues=[],", "        explanation=\"Coherent.\",", "        confidence=0.9,", "        entity_linkage_plausible=True,", "        entity_linkage_explanation=None,", "    )", "    html = render_report_html(_doc([_ctx(E1), _ctx(E2)], grades=[bad, good], flagged_count=1))", "    assert \"Flagged events (1)\" in html", "    assert \"Clean events (1)\" in html", "    assert html.index(\"Two different events on one row.\") < html.index(\"<details>\")", "", "", "def test_duplicate_pair_renders_context_for_both_events():", "    pair = QADuplicatePair(", "        event_id_a=E1,", "        event_id_b=E2,", "        same_event=True,", "        confidence=0.97,", "        explanation=\"Same Reno plant announcement.\",", "    )", "    html = render_report_html(", "        _doc(", "            [_ctx(E1, title=\"Delta A\"), _ctx(E2, title=\"Delta B\")],", "            pairs=[pair],", "            duplicate_pair_count=1,", "        )", "    )", "    assert \"Same Reno plant announcement.\" in html", "    assert \"Delta A\" in html and \"Delta B\" in html", "", "", "def test_pair_naming_an_ungraded_event_is_skipped_not_half_rendered():", "    \"\"\"A pair referencing missing context must not produce a blank-sided card.\"\"\"", "    pair = QADuplicatePair(", "        event_id_a=E1,", "        event_id_b=E3,", "        same_event=True,", "        confidence=0.9,", "        explanation=\"Dangling reference.\",", "    )", "    html = render_report_html(_doc([_ctx(E1)], pairs=[pair], duplicate_pair_count=1))", "    assert \"Dangling reference.\" not in html", "    assert \"No missed duplicates detected\" in html", "", "", "def test_page_is_self_contained():", "    html = render_report_html(_doc([_ctx(E1)]))", "    assert \"<script\" not in html.lower()", "    assert \"http://\" not in html and \"https://\" not in html", "", "", "def test_duplicate_pair_member_is_not_also_listed_as_clean():", "    \"\"\"A paired event with a passing individual grade is still a finding.", "", "    Duplicate detection is cross-sample: event_valid and merge_correct can both be", "    fine while the event is half of a pair that should have been merged. Listing it", "    again under \"Clean events\" would tell a reviewer the opposite of what the", "    duplicates section just said.", "    \"\"\"", "    good_a = QAEventGrade(", "        event_id=E1,", "        event_valid=True,", "        merge_correct=None,", "        issues=[],", "        explanation=\"Coherent.\",", "        confidence=0.95,", "        entity_linkage_plausible=True,", "        entity_linkage_explanation=None,", "    )", "    good_b = QAEventGrade(", "        event_id=E2,", "        event_valid=True,", "        merge_correct=None,", "        issues=[],", "        explanation=\"Coherent.\",", "        confidence=0.95,", "        entity_linkage_plausible=True,", "        entity_linkage_explanation=None,", "    )", "    pair = QADuplicatePair(", "        event_id_a=E1,", "        event_id_b=E2,", "        same_event=True,", "        confidence=0.97,", "        explanation=\"Same announcement, never merged.\",", "    )", "    html = render_report_html(", "        _doc(", "            [_ctx(E1, title=\"Delta A\"), _ctx(E2, title=\"Delta B\")],", "            grades=[good_a, good_b],", "            pairs=[pair],", "            duplicate_pair_count=1,", "        )", "    )", "    assert \"Possible missed duplicates (1)\" in html", "    assert \"Clean events (0)\" in html", "    # Each paired event is rendered once, in the duplicates section only.", "    assert html.count(\"Delta A\") == 1", "", "", "def test_paired_but_not_flagged_event_shows_its_own_grade():", "    \"\"\"A pair member's individual verdict must be ON its pair card.", "", "    Rendering pair members with no grade put a paired-but-passing event's verdict", "    and explanation nowhere on the page: it is excluded from \"Clean events\" by", "    design, so the pair card is its only appearance. The JSON had the grade the", "    whole time, which is what made the omission hard to see.", "    \"\"\"", "    good_a = QAEventGrade(", "        event_id=E1,", "        event_valid=True,", "        merge_correct=None,", "        issues=[],", "        explanation=\"A reads coherent on its own.\",", "        confidence=0.95,", "        entity_linkage_plausible=True,", "        entity_linkage_explanation=None,", "    )", "    good_b = QAEventGrade(", "        event_id=E2,", "        event_valid=True,", "        merge_correct=None,", "        issues=[],", "        explanation=\"B reads coherent on its own.\",", "        confidence=0.95,", "        entity_linkage_plausible=True,", "        entity_linkage_explanation=None,", "    )", "    pair = QADuplicatePair(", "        event_id_a=E1,", "        event_id_b=E2,", "        same_event=True,", "        confidence=0.97,", "        explanation=\"Same announcement, never merged.\",", "    )", "    html = render_report_html(", "        _doc(", "            [_ctx(E1, title=\"Delta A\"), _ctx(E2, title=\"Delta B\")],", "            grades=[good_a, good_b],", "            pairs=[pair],", "            duplicate_pair_count=1,", "        )", "    )", "    assert \"Clean events (0)\" in html", "    # Once each, in the duplicates section, each carrying its OWN explanation.", "    assert html.count(\"Delta A\") == 1", "    assert html.count(\"Delta B\") == 1", "    assert html.count(\"A reads coherent on its own.\") == 1", "    assert html.count(\"B reads coherent on its own.\") == 1", "    # Neither is flagged, so neither is cross-listed.", "    assert \"Also shown under\" not in html", "", "", "def test_flagged_and_paired_event_is_cross_listed_in_both_sections():", "    \"\"\"A flagged event that is also paired is rendered in BOTH sections.", "", "    The two are independent findings -- its own grade judged the event, the pair", "    grader judged a possible missed merge -- so dropping it from \"Flagged events\"", "    would hide the individual finding and make that section disagree with the", "    flagged_count in its own header. The duplicate appearance is therefore", "    deliberate, and the flagged card says so.", "    \"\"\"", "    bad_a = QAEventGrade(", "        event_id=E1,", "        event_valid=True,", "        merge_correct=False,", "        issues=[],", "        explanation=\"A merged two different events.\",", "        confidence=0.9,", "        entity_linkage_plausible=True,", "        entity_linkage_explanation=None,", "    )", "    good_b = QAEventGrade(", "        event_id=E2,", "        event_valid=True,", "        merge_correct=None,", "        issues=[],", "        explanation=\"B reads coherent on its own.\",", "        confidence=0.95,", "        entity_linkage_plausible=True,", "        entity_linkage_explanation=None,", "    )", "    pair = QADuplicatePair(", "        event_id_a=E1,", "        event_id_b=E2,", "        same_event=True,", "        confidence=0.97,", "        explanation=\"Same announcement, never merged.\",", "    )", "    html = render_report_html(", "        _doc(", "            [_ctx(E1, title=\"Delta A\"), _ctx(E2, title=\"Delta B\")],", "            grades=[bad_a, good_b],", "            pairs=[pair],", "            flagged_count=1,", "            duplicate_pair_count=1,", "        )", "    )", "    assert \"Flagged events (1)\" in html", "    assert \"Possible missed duplicates (1)\" in html", "    assert \"Clean events (0)\" in html", "    # A is cross-listed: flagged card AND pair card, with its verdict on both.", "    assert html.count(\"Delta A\") == 2", "    assert html.count(\"A merged two different events.\") == 2", "    # B appears only under duplicates, with its own verdict.", "    assert html.count(\"Delta B\") == 1", "    assert html.count(\"B reads coherent on its own.\") == 1", "    # The note is on the flagged card only, so it is not repeated on the pair card.", "    assert html.count(\"Also shown under\") == 1", "", "", "def test_pair_card_partial_evidence_can_cite_its_verdict():", "    \"\"\"With the member's grade on the card, the coverage notice has a verdict to", "    qualify -- the sentence and the verdict must appear together or not at all.", "", "    The graded event here passes (``merge_correct=True``), so it is NOT flagged and", "    the pair card is its only appearance on the page. That is what makes the", "    assertion about the pair card rather than about a flagged card elsewhere: a", "    merge_correct=False fixture would be flagged, and the sentence would render in", "    the flagged section even with the pair-card grade suppressed.", "    \"\"\"", "    graded = QAEventGrade(", "        event_id=E1,", "        event_valid=True,", "        merge_correct=True,", "        issues=[],", "        explanation=\"Merge looks right on the documents shown.\",", "        confidence=0.9,", "        entity_linkage_plausible=True,", "        entity_linkage_explanation=None,", "    )", "    good_b = QAEventGrade(", "        event_id=E2,", "        event_valid=True,", "        merge_correct=None,", "        issues=[],", "        explanation=\"B reads coherent on its own.\",", "        confidence=0.95,", "        entity_linkage_plausible=True,", "        entity_linkage_explanation=None,", "    )", "    pair = QADuplicatePair(", "        event_id_a=E1,", "        event_id_b=E2,", "        same_event=True,", "        confidence=0.9,", "        explanation=\"Same announcement, never merged.\",", "    )", "    html = render_report_html(", "        _doc(", "            [_ctx(E1, included=2, linked_document_count=7), _ctx(E2)],", "            grades=[graded, good_b],", "            pairs=[pair],", "            duplicate_pair_count=1,", "        )", "    )", "    assert \"Flagged events (0)\" in html", "    assert \"2 of 7\" in html", "    assert \"Any merge verdict above\" in html", "    assert html.count(\"Merge looks right on the documents shown.\") == 1", "", "", "def test_unpaired_clean_event_still_appears_in_clean():", "    \"\"\"The duplicate exclusion must not swallow genuinely clean events.\"\"\"", "    good = QAEventGrade(", "        event_id=E1,", "        event_valid=True,", "        merge_correct=None,", "        issues=[],", "        explanation=\"Coherent.\",", "        confidence=0.95,", "        entity_linkage_plausible=True,", "        entity_linkage_explanation=None,", "    )", "    html = render_report_html(_doc([_ctx(E1)], grades=[good]))", "    assert \"Clean events (1)\" in html", "", "", "# --------------------------------------------------------------------------- #", "# The stylesheet must NOT be escaped, and the two flagged counts must agree.", "# --------------------------------------------------------------------------- #", "", "", "def test_stylesheet_is_not_escaped_inside_the_style_element():", "    \"\"\"``<style>`` is a raw-text element: browsers do not decode character", "    references there. An autoescaped ``\"Segoe UI\"`` would reach the CSS parser as", "    ``&#34;Segoe UI&#34;`` -- an invalid token that drops the whole ``font:``", "    shorthand, losing font-family, font-size and line-height on ``body``.", "    \"\"\"", "    html = render_report_html(_doc([_ctx(E1)]))", "    style_block = html.split(\"<style>\")[1].split(\"</style>\")[0]", "", "    assert '\"Segoe UI\"' in style_block", "    assert \"&#34;\" not in style_block", "    assert \"&quot;\" not in style_block", "", "", "def test_flagged_heading_matches_the_count_the_cli_computes():", "    \"\"\"The page states the flagged count twice -- header row and section heading --", "    and the CLI derives the header's number by summing ``is_flagged``. Rendering", "    must sum the SAME predicate or a reviewer cannot tell which number to believe.", "    \"\"\"", "    grades = [", "        QAEventGrade(", "            event_id=E1,", "            event_valid=True,", "            merge_correct=False,", "            issues=[],", "            explanation=\"Wrong merge.\",", "            confidence=0.9,", "            entity_linkage_plausible=True,", "            entity_linkage_explanation=None,", "        ),", "        QAEventGrade(", "            event_id=E2,", "            event_valid=False,", "            merge_correct=None,", "            issues=[],", "            explanation=\"Not an event.\",", "            confidence=0.9,", "            entity_linkage_plausible=True,", "            entity_linkage_explanation=None,", "        ),", "        QAEventGrade(", "            event_id=E3,", "            event_valid=True,", "            merge_correct=True,", "            issues=[],", "            explanation=\"Fine.\",", "            confidence=0.9,", "            entity_linkage_plausible=True,", "            entity_linkage_explanation=None,", "        ),", "    ]", "    # Exactly the expression in cli/qa_report.py, over the same imported predicate.", "    flagged_count = sum(1 for g in grades if is_flagged(g))", "", "    # Pinned so the assertion below cannot pass vacuously: were is_flagged to", "    # degenerate to always-False, count and heading would agree at zero.", "    assert flagged_count == 2", "", "    html = render_report_html(", "        _doc(", "            [_ctx(E1), _ctx(E2), _ctx(E3)],", "            grades=grades,", "            flagged_count=flagged_count,", "        )", "    )", "    assert f\"Flagged events ({flagged_count})\" in html", "    assert \"<td>Flagged</td><td>2 event(s)\" in html", "    assert \"Clean events (1)\" in html", "", "", "# --------------------------------------------------------------------------- #", "# DAT-8294: entity-linkage rendering.", "#", "# Assertions hook on stable data-testid attributes, not on prose: the wording", "# above them is meant to be reworded without breaking the suite.", "# --------------------------------------------------------------------------- #", "", "", "def _bucket(day: int, eligible: int, linked: int, partial: bool = False) -> LinkageCoverageBucket:", "    return LinkageCoverageBucket(", "        bucket_date=date(2026, 9, day), eligible=eligible, linked=linked, partial=partial", "    )", "", "", "def _interval_table(html: str) -> str:", "    \"\"\"The interval table's markup alone, sliced from its own test hook.\"\"\"", "    start = html.index('data-testid=\"linkage-intervals\"')", "    return html[start : html.index(\"</table>\", start)]", "", "", "def _cell(html: str, testid: str) -> str:", "    \"\"\"Return the text inside the element carrying ``data-testid=testid``.\"\"\"", "    match = re.search(rf'data-testid=\"{testid}\"[^>]*>(.*?)<', html, re.S)", "    assert match is not None, f\"no element carrying data-testid={testid!r}\"", "    return match.group(1).strip()", "", "", "def test_linkage_health_failed_is_visually_distinct_from_healthy() -> None:", "    failed = render_report_html(_doc([_ctx(E1)], linkage_health=\"failed\"))", "    healthy = render_report_html(_doc([_ctx(E1)], linkage_health=\"healthy\"))", "", "    assert 'class=\"state failed\"' in failed", "    assert 'class=\"state healthy\"' in healthy", "    assert \"FAILED\" in _cell(failed, \"linkage-health\")", "    assert _cell(failed, \"linkage-health\") != _cell(healthy, \"linkage-health\")", "", "", "def test_linkage_health_not_assessed_reads_as_neither() -> None:", "    html = render_report_html(_doc([_ctx(E1)], linkage_health=\"not_assessed\"))", "    state = _cell(html, \"linkage-health\")", "    assert \"not assessed\" in state", "    assert \"FAILED\" not in state", "    assert \"healthy\" not in state", "", "", "def test_interval_table_renders_a_row_per_bucket_with_a_computed_percentage() -> None:", "    buckets = [_bucket(14, 100, 80), _bucket(15, 50, 5)]", "    html = render_report_html(_doc([_ctx(E1)], linkage_coverage=buckets))", "", "    assert 'data-testid=\"linkage-intervals\"' in html", "    assert \"2026-09-14\" in html and \"2026-09-15\" in html", "    assert \"80.0%\" in html  # 80/100, computed at render time from the two integers", "    assert \"10.0%\" in html  # 5/50", "", "", "def test_an_empty_interval_renders_as_not_assessed_never_as_zero_percent() -> None:", "    \"\"\"A day with no eligible event has no percentage.", "", "    Rendering ``0%`` there would report an idle day as a total linkage outage,", "    which is the failure mode that makes an alarm not worth acting on.", "    \"\"\"", "    html = render_report_html(_doc([_ctx(E1)], linkage_coverage=[_bucket(14, 0, 0)]))", "", "    table = _interval_table(html)", "    assert \"not assessed\" in table", "    assert \"0.0%\" not in table", "", "", "def test_a_zero_link_interval_with_events_does_render_zero_percent_and_is_marked() -> None:", "    html = render_report_html(_doc([_ctx(E1)], linkage_coverage=[_bucket(14, 120, 0)]))", "    table = _interval_table(html)", "    assert \"0.0%\" in table", "    assert 'class=\"failed\"' in table  # the row itself is marked, not just the header", "", "", "def test_partial_buckets_are_labelled_rather_than_dropped() -> None:", "    buckets = [_bucket(14, 10, 8, partial=True), _bucket(15, 10, 8)]", "    html = render_report_html(_doc([_ctx(E1)], linkage_coverage=buckets))", "    assert \"(partial)\" in html", "", "", "def test_interval_table_scrolls_inside_its_own_container() -> None:", "    \"\"\"A seven-row table must not make the page body scroll sideways on a phone.\"\"\"", "    buckets = [_bucket(14 + i, 100, 80) for i in range(7)]", "    html = render_report_html(_doc([_ctx(E1)], linkage_coverage=buckets))", "", "    table_at = html.index('data-testid=\"linkage-intervals\"')", "    preceding = html[:table_at]", "    assert 'class=\"scroller\"' in preceding[preceding.rindex(\"<div\") :]", "    assert \"overflow-x: auto\" in html  # the container, not the body, scrolls", "", "", "def test_sampled_zero_link_count_is_labelled_about_the_graded_sample() -> None:", "    html = render_report_html(_doc([_ctx(E1)], sampled_zero_link_count=4))", "    assert _cell(html, \"sampled-zero-links\") == \"4\"", "    assert \"graded event\" in html  # scoped to the sample, not the population", "", "", "def test_unexpected_entity_loss_count_and_the_dropped_gap_are_both_rendered() -> None:", "    html = render_report_html(", "        _doc([_ctx(E1)], unexpected_entity_loss_count=3, dropped_entity_loss_count=1)", "    )", "    assert _cell(html, \"unexpected-entity-loss\") == \"3\"", "    assert \"1 dropped for grader budget\" in html", "", "", "def test_unmeasured_counts_say_so_rather_than_rendering_zero() -> None:", "    \"\"\"``None`` means \"not measured\", and 0 means \"measured zero\".", "", "    A report written before this ticket carries neither count. Printing ``0``", "    would turn \"not recorded\" into \"measured zero\" -- the same class of false", "    clean the bucketed measure exists to avoid.", "    \"\"\"", "    html = render_report_html(_doc([_ctx(E1)]))", "    assert _cell(html, \"sampled-zero-links\") == NOT_MEASURED", "    assert _cell(html, \"unexpected-entity-loss\") == NOT_MEASURED", "", "", "def test_per_event_pre_trim_direct_link_count_is_shown_beside_the_document_count() -> None:", "    html = render_report_html(_doc([_ctx(E1, direct_link_count=7, linked_document_count=2)]))", "    assert _cell(html, \"event-direct-links\") == \"7\"", "", "", "def test_per_event_entity_loss_state_renders_all_three_states() -> None:", "    for state, expected in ((\"loss\", \"yes\"), (\"no_loss\", \"no\"), (\"not_assessed\", \"not assessed\")):", "        html = render_report_html(_doc([_ctx(E1, entity_loss_state=state)]))", "        assert _cell(html, \"event-entity-loss\") == expected", "        assert f'class=\"state {state}\"' in html", "", "", "def test_the_page_states_what_the_measure_does_and_does_not_mean() -> None:", "    \"\"\"A zero-link event is not by itself a defect, and the page must say so.", "", "    Roughly 30-50% of events legitimately carry no directly-mentioned entity. A", "    page that implied otherwise would train its reader to ignore it.", "    \"\"\"", "    html = render_report_html(_doc([_ctx(E1)], linkage_coverage=[_bucket(14, 10, 8)]))", "    assert \"directly mentioned\" in html.lower()", "    assert \"not</strong> by itself a\" in html or \"not by itself a\" in html", "", "", "def test_linkage_rendering_keeps_the_page_self_contained() -> None:", "    buckets = [_bucket(14 + i, 100, 80) for i in range(7)]", "    html = render_report_html(_doc([_ctx(E1)], linkage_coverage=buckets))", "    assert \"<script\" not in html.lower()", "    assert \"https://\" not in html", "", "", "# --------------------------------------------------------------------------- #", "# DAT-8294 R7/AC3: entity identity and the per-event check status.", "# --------------------------------------------------------------------------- #", "", "", "def test_complete_event_renders_its_entities_by_name_and_type() -> None:", "    \"\"\"AC3 on the page: a bare UUID told a reader nothing either.\"\"\"", "    html = render_report_html(", "        _doc(", "            [", "                _ctx(", "                    E1,", "                    entity_check_status=\"complete\",", "                    entities=[", "                        _entity_view(\"Northwind Traders\", \"CVW\"),", "                        _entity_view(\"Iberian Logistics Market\", \"MVW\"),", "                    ],", "                )", "            ]", "        )", "    )", "", "    assert _cell(html, \"event-entity-check-complete\") != \"\"", "    listed = re.search(r'data-testid=\"event-entity-list\"(.*?)</div>', html, re.S)", "    assert listed is not None", "    assert \"Northwind Traders\" in listed.group(1)", "    assert \"CVW\" in listed.group(1)", "    assert \"Iberian Logistics Market\" in listed.group(1)", "    assert \"MVW\" in listed.group(1)", "", "", "@pytest.mark.parametrize(\"cause\", [\"entity_cap\", \"budget_trim\", \"name_truncated\"])", "def test_partial_event_names_the_specific_cause(cause: str) -> None:", "    \"\"\" \"Partial\" without the cause leaves three candidate fixes and no way to pick.", "", "    Asserted per cause, and against the label text the module owns rather than", "    against prose written into the test, so a reworded label cannot pass silently", "    under a generic substring check.", "    \"\"\"", "    html = render_report_html(", "        _doc([_ctx(E1, entity_check_status=\"partial\", entity_loss_causes=[cause])])", "    )", "", "    assert _cell(html, \"event-entity-check-partial\") != \"\"", "    assert ENTITY_CAUSE_LABELS[cause] in html", "", "", "def test_partial_status_has_its_own_class_so_it_cannot_be_skimmed_past() -> None:", "    partial = render_report_html(_doc([_ctx(E1, entity_check_status=\"partial\")]))", "    complete = render_report_html(_doc([_ctx(E1, entity_check_status=\"complete\")]))", "", "    assert 'class=\"state partial_check\"' in partial", "    assert 'class=\"state partial_check\"' not in complete", "    assert 'class=\"state complete\"' in complete", "", "", "def test_not_run_distinguishes_no_links_from_all_evidence_removed() -> None:", "    \"\"\"Different remedies, so they must not render identically.", "", "    No links at all is a linkage question; every entity removed is a budget one.", "    \"\"\"", "    no_links = render_report_html(", "        _doc([_ctx(E1, entity_check_status=\"not_run\", entity_loss_causes=[], entities=[])])", "    )", "    removed = render_report_html(", "        _doc(", "            [", "                _ctx(", "                    E1,", "                    entity_check_status=\"not_run\",", "                    entity_loss_causes=[\"budget_trim\"],", "                    entities=[],", "                )", "            ]", "        )", "    )", "", "    assert _cell(no_links, \"event-entity-no-links\") == NO_ENTITY_LINKS", "    assert \"event-entity-all-removed\" not in no_links", "    assert ALL_ENTITIES_REMOVED in _cell(removed, \"event-entity-all-removed\")", "    assert \"event-entity-no-links\" not in removed", "    assert 'class=\"state not_run\"' in no_links and 'class=\"state not_run\"' in removed", "", "", "def test_a_truncated_name_carries_a_trailing_ellipsis() -> None:", "    \"\"\"A shortened name must not read as the entity's real one.\"\"\"", "    cut = render_report_html(", "        _doc(", "            [", "                _ctx(", "                    E1,", "                    entity_check_status=\"partial\",", "                    entity_loss_causes=[\"name_truncated\"],", "                    entities=[_entity_view(\"Very Long Corporate Nam\", name_truncated=True)],", "                )", "            ]", "        )", "    )", "    intact = render_report_html(_doc([_ctx(E1, entities=[_entity_view(\"Acme Corporation\")])]))", "", "    assert f\"Very Long Corporate Nam{TRUNCATION_MARK}\" in cut", "    assert TRUNCATION_MARK not in intact", "", "", "def test_entity_name_from_scraped_text_is_escaped() -> None:", "    \"\"\"``display_name`` is operator-visible data of external origin, like every", "    other interpolated value on this page.\"\"\"", "    html = render_report_html(", "        _doc([_ctx(E1, entities=[_entity_view('<script>alert(\"x\")</script>')])])", "    )", "", "    assert \"<script>alert\" not in html", "    assert \"&lt;script&gt;\" in html", "", "", "# --------------------------------------------------------------------------- #", "# DAT-8294 AC3: the grader's plausibility verdict, its explanation, and the", "# composition of the flagged section. Asserted by data-testid, never by prose.", "# --------------------------------------------------------------------------- #", "", "", "def _grade(", "    event_id: UUID,", "    *,", "    event_valid: bool = True,", "    merge_correct: bool | None = None,", "    plausible: bool | None = True,", "    linkage_explanation: str | None = None,", ") -> QAEventGrade:", "    return QAEventGrade(", "        event_id=event_id,", "        event_valid=event_valid,", "        merge_correct=merge_correct,", "        entity_linkage_plausible=plausible,", "        entity_linkage_explanation=linkage_explanation,", "        issues=[],", "        explanation=\"graded\",", "        confidence=0.9,", "    )", "", "", "def test_a_plausible_verdict_renders_as_plausible_and_does_not_flag() -> None:", "    html = render_report_html(_doc([_ctx(E1)], grades=[_grade(E1, plausible=True)]))", "", "    assert _cell(html, \"event-linkage-verdict-plausible\") == LINKAGE_PLAUSIBLE", "    assert \"event-linkage-verdict-implausible\" not in html", "    assert \"No events flagged in this run.\" in html", "", "", "def test_an_implausible_verdict_renders_its_explanation_and_reaches_the_flagged_section() -> None:", "    \"\"\"A verdict with no consequence is not a flag (R5).", "", "    The event must reach the flagged SECTION, not merely carry a red tag on a card", "    filed under \"Clean events\".", "    \"\"\"", "    grade = _grade(", "        E1,", "        plausible=False,", "        linkage_explanation=\"Globex Inc. has nothing to do with this event\",", "    )", "    html = render_report_html(_doc([_ctx(E1)], grades=[grade], flagged_count=1))", "", "    assert _cell(html, \"event-linkage-verdict-implausible\") == LINKAGE_IMPLAUSIBLE", "    assert (", "        _cell(html, \"event-linkage-explanation\") == \"Globex Inc. has nothing to do with this event\"", "    )", "    assert \"<h2>Flagged events (1)</h2>\" in html", "    assert \"No events flagged in this run.\" not in html", "    assert _cell(html, \"flag-reason-entity_linkage\") == FLAG_REASON_LABELS[\"entity_linkage\"]", "", "", "def test_a_null_verdict_renders_as_not_applicable_naming_no_links() -> None:", "    \"\"\"Null is NOT a pass. A blank would read as a check that ran and found nothing.\"\"\"", "    ctx = _ctx(E1, entity_check_status=\"not_run\", entity_loss_causes=[], entities=[])", "    html = render_report_html(_doc([ctx], grades=[_grade(E1, plausible=None)]))", "", "    assert _cell(html, \"event-linkage-verdict-na\") == LINKAGE_NOT_APPLICABLE", "    assert NO_ENTITY_LINKS in _cell(html, \"event-linkage-na-no-links\")", "    assert \"event-linkage-na-removed\" not in html", "    assert \"event-linkage-verdict-plausible\" not in html", "", "", "def test_a_null_verdict_names_evidence_removed_when_that_is_why() -> None:", "    \"\"\"The two shapes of \"nothing was shown\" need different responses: one is a", "    linkage question, the other a budget to raise. The status alone cannot say which,", "    which is why plan 02's cause list is carried beside it.\"\"\"", "    ctx = _ctx(E1, entity_check_status=\"not_run\", entity_loss_causes=[\"budget_trim\"], entities=[])", "    html = render_report_html(_doc([ctx], grades=[_grade(E1, plausible=None)]))", "", "    assert _cell(html, \"event-linkage-verdict-na\") == LINKAGE_NOT_APPLICABLE", "    assert ALL_ENTITIES_REMOVED in _cell(html, \"event-linkage-na-removed\")", "    assert \"event-linkage-na-no-links\" not in html", "", "", "def test_the_flagged_section_names_which_check_flagged_each_event() -> None:", "    \"\"\"The composition of flagged_count is readable, not inferred.", "", "    Three flagged events for three different reasons, plus a clean one: a reader can", "    see WHICH check put each event there.", "    \"\"\"", "    invalid = _grade(E1, event_valid=False)", "    bad_merge = _grade(E2, merge_correct=False)", "    implausible = _grade(E3, plausible=False, linkage_explanation=\"an unrelated industry\")", "    html = render_report_html(", "        _doc(", "            [_ctx(E1), _ctx(E2), _ctx(E3)],", "            grades=[invalid, bad_merge, implausible],", "            flagged_count=3,", "        )", "    )", "", "    assert \"<h2>Flagged events (3)</h2>\" in html", "    assert f'data-testid=\"flag-reason-invalid\">{FLAG_REASON_LABELS[\"invalid\"]}' in html", "    assert f'data-testid=\"flag-reason-merge\">{FLAG_REASON_LABELS[\"merge\"]}' in html", "    assert (", "        f'data-testid=\"flag-reason-entity_linkage\">{FLAG_REASON_LABELS[\"entity_linkage\"]}' in html", "    )", "", "", "def test_existing_flag_reasons_render_exactly_as_before() -> None:", "    \"\"\"Pinned regression, not an \"unchanged\" assertion.", "", "    An invalid event and a ``merge_correct is False`` event each reach the flagged", "    section on their own, with a PLAUSIBLE linkage verdict that adds nothing -- so", "    the fourth check cannot be what put them there.", "    \"\"\"", "    invalid = render_report_html(", "        _doc([_ctx(E1)], grades=[_grade(E1, event_valid=False, plausible=True)], flagged_count=1)", "    )", "    bad_merge = render_report_html(", "        _doc([_ctx(E1)], grades=[_grade(E1, merge_correct=False, plausible=True)], flagged_count=1)", "    )", "", "    for html, reason in ((invalid, \"invalid\"), (bad_merge, \"merge\")):", "        assert \"<h2>Flagged events (1)</h2>\" in html", "        assert _cell(html, f\"flag-reason-{reason}\") == FLAG_REASON_LABELS[reason]", "        assert \"flag-reason-entity_linkage\" not in html", "        assert _cell(html, \"event-linkage-verdict-plausible\") == LINKAGE_PLAUSIBLE", "", "", "def test_the_linkage_explanation_is_escaped() -> None:", "    \"\"\"Free-form model output over scraped text: untrusted, like every other value.\"\"\"", "    grade = _grade(E1, plausible=False, linkage_explanation='<img src=x onerror=\"alert(1)\">')", "    html = render_report_html(_doc([_ctx(E1)], grades=[grade], flagged_count=1))", "", "    assert \"<img src=x\" not in html", "    assert \"&lt;img\" in html", "", "", "# --------------------------------------------------------------------------- #", "# A degraded report must not read as a clean one (PR #495 review).", "# --------------------------------------------------------------------------- #", "", "", "def _degraded_doc(events) -> QAReportDocument:", "    \"\"\"A report whose grading failed: deterministic half only, no grades.\"\"\"", "    return QAReportDocument(", "        metadata=_metadata(", "            sampled_count=len(events),", "            flagged_count=None,", "            duplicate_pair_count=None,", "            chat_model=None,", "            fallback_used=None,", "        ),", "        sampled_event_ids=[e.event_id for e in events],", "        llm_report=None,", "        grading_state=\"failed\",", "        grading_failure=\"grading\",", "        events=events,", "    )", "", "", "def test_a_degraded_report_makes_no_affirmative_clean_claim() -> None:", "    \"\"\"Absence of a verdict must never render as a passing verdict.", "", "    A banner alone is not enough, which is what the first attempt at this got wrong.", "    With grades absent, every event is neither flagged nor paired, so the page", "    otherwise printed \"No events flagged in this run\", \"No missed duplicates detected", "    in this run\", and listed every ungraded event under \"Clean events\" -- three", "    affirmative grading conclusions on a run where no model answered. A reader", "    skimming past the banner would take the report as a pass.", "    \"\"\"", "    html = render_report_html(_degraded_doc([_ctx(E1, entity_check_status=\"not_run\")]))", "", "    assert 'data-testid=\"grading-failed-banner\"' in html", "    # The three false claims, each asserted ABSENT by its own text.", "    assert \"No events flagged in this run\" not in html", "    assert \"No missed duplicates detected in this run\" not in html", "    assert \"Clean events\" not in html", "    # And the honest replacements, each present.", "    assert 'data-testid=\"flagged-ungraded\"' in html", "    assert 'data-testid=\"duplicates-ungraded\"' in html", "    assert 'data-testid=\"ungraded-events-summary\"' in html", "    assert \"Ungraded events\" in html", "    # \"graded event(s)\" would misdescribe the zero-link denominator.", "    assert \"graded event(s)\" not in html", "    assert \"sampled (ungraded) event(s)\" in html", "", "", "def test_a_complete_report_keeps_its_clean_language() -> None:", "    \"\"\"The degraded branches must not leak into a run that DID grade.", "", "    Without this, suppressing the clean language everywhere would pass the test above", "    while destroying the normal page -- a fix that satisfies its own assertion by", "    breaking the case it was not about.", "    \"\"\"", "    html = render_report_html(_doc([_ctx(E1)]))", "", "    assert 'data-testid=\"grading-failed-banner\"' not in html", "    assert \"No events flagged in this run\" in html", "    assert \"No missed duplicates detected in this run\" in html", "    assert \"Clean events\" in html", "    assert \"graded event(s)\" in html", "", "", "def test_a_degraded_report_does_not_explain_why_entities_are_missing() -> None:", "    \"\"\"The two ``not_run`` sub-reasons are grading answers, and neither was earned.", "", "    A degraded run forces every event's status to ``not_run``, which made the template", "    choose between \"this event has no entity links at all\" (no causes) and \"every linked", "    entity was removed before grading\" (causes present). Both are read off evidence the", "    grader never saw. An event carrying real entities would render \"no entity links at", "    all\" directly above the list of its entities -- the same class of false statement", "    this whole change exists to remove, on the artifact the ticket designates as", "    authoritative.", "", "    The previous degraded test built exactly this shape and asserted nothing about it.", "    \"\"\"", "    ctx = _ctx(E1, entity_check_status=\"not_run\", entities=[_entity_view()])", "    html = render_report_html(_degraded_doc([ctx]))", "", "    assert 'data-testid=\"event-entity-not-graded\"' in html", "    assert 'data-testid=\"event-entity-no-links\"' not in html, (", "        \"an event with entities must not be described as having none\"", "    )", "    assert 'data-testid=\"event-entity-all-removed\"' not in html", "    # The contradiction this guards against: the entity list is rendered right below.", "    assert 'data-testid=\"event-entity-list\"' in html", "", "", "def test_a_degraded_document_cannot_claim_a_completed_entity_check() -> None:", "    \"\"\"``complete`` would assert a check no model performed.", "", "    Enforced on the MODEL, not in the renderer: the renderer prints what it is given,", "    so the contradiction has to be unconstructable rather than merely unproduced.", "    \"\"\"", "    with pytest.raises(ValidationError, match=\"not_run\"):", "        QAReportDocument(", "            metadata=_metadata(", "                sampled_count=1,", "                flagged_count=None,", "                duplicate_pair_count=None,", "                chat_model=None,", "                fallback_used=None,", "            ),", "            sampled_event_ids=[E1],", "            llm_report=None,", "            grading_state=\"failed\",", "            grading_failure=\"grading\",", "            events=[_ctx(E1, entity_check_status=\"complete\")],", "        )", "", "", "# --------------------------------------------------------------------------- #", "# Unexpected entity loss is a defect, so it must not be filed under \"Clean", "# events\" (PR #495 human review).", "# --------------------------------------------------------------------------- #", "", "", "def _collapsed_section(html: str) -> str:", "    \"\"\"The contents of the LAST collapsed <details> on the page.", "", "    That is \"Clean events\" on a complete report and \"Ungraded events\" on a degraded", "    one. Slicing on the <details> element rather than on a heading is what makes the", "    assertion mean \"filed under this heading\" instead of \"absent from the page\".", "    \"\"\"", "    start = html.rindex(\"<details>\")", "    return html[start:]", "", "", "def _unassessed_section(html: str) -> str:", "    \"\"\"The contents of the \"Entity loss not assessed\" <details>.\"\"\"", "    start = html.index('data-testid=\"entity-loss-unknown-summary\"')", "    return html[start : html.index(\"</details>\", start)]", "", "", "def _loss_section(html: str) -> str:", "    \"\"\"The markup between the loss heading and the section that follows it.", "", "    Absence from \"Clean events\" is only half the claim the tests below make. Without", "    this slice, a change that dropped the loss CARDS while keeping the heading -- a", "    render guarded on ``grade is not None``, say -- would leave every assertion green", "    and the defect invisible on the page.", "    \"\"\"", "    start = html.index(\"<h2>Unexpected entity loss\")", "    return html[start : html.index(\"<h2>\", start + 4)]", "", "", "def test_an_entity_loss_event_does_not_land_under_clean_events() -> None:", "    \"\"\"AC1's \"always a defect\" state has to reach a section a reader opens.", "", "    Before this, a loss event carried a red \"yes\" tag on a card filed under the", "    collapsed \"Clean events\" heading: the exact verdict-with-no-consequence shape R5", "    rejects for the implausibility verdict. ``is_flagged`` cannot see it -- loss is", "    deterministic and lives outside every grade -- so the event needs its own section.", "    \"\"\"", "    lost = _ctx(E1, title=\"Lost evidence\", entity_loss_state=\"loss\")", "    keep = _ctx(E2, title=\"Kept evidence\", entity_loss_state=\"no_loss\")", "    html = render_report_html(_doc([lost, keep], grades=[_grade(E1), _grade(E2)]))", "", "    assert \"<h2>Unexpected entity loss (1)</h2>\" in html", "    assert str(E1) not in _collapsed_section(html)", "    # The control on the slice: a non-loss event still reaches \"Clean events\", so the", "    # assertion above cannot pass by the section being empty or the slice being wrong.", "    assert \"<summary>Clean events (1)</summary>\" in html", "    assert str(E2) in _collapsed_section(html)", "", "", "def test_an_entity_loss_event_that_is_also_flagged_appears_in_both_sections() -> None:", "    \"\"\"Two independent findings about one event, as with the duplicate-pair overlap.", "", "    The grade flagged it; the merge separately dropped entity evidence. Rendering it", "    once would drop whichever finding lost the coin toss.", "    \"\"\"", "    lost = _ctx(E1, entity_loss_state=\"loss\")", "    html = render_report_html(_doc([lost], grades=[_grade(E1, event_valid=False)], flagged_count=1))", "", "    assert \"<h2>Flagged events (1)</h2>\" in html", "    assert \"<h2>Unexpected entity loss (1)</h2>\" in html", "    assert html.count(f\"{E1} \u00b7\") == 2", "    assert \"<summary>Clean events (0)</summary>\" in html", "", "", "def test_the_flagged_count_in_the_meta_table_is_unmoved_by_entity_loss() -> None:", "    \"\"\"``flagged_count`` is defined over grades and the CLI computes it there.", "", "    Folding loss into ``is_flagged`` would have put the flagged heading and the count", "    in the table above it permanently at odds for any run with a loss event.", "    \"\"\"", "    lost = _ctx(E1, entity_loss_state=\"loss\")", "    html = render_report_html(_doc([lost], grades=[_grade(E1)], flagged_count=0))", "", "    assert \"<h2>Flagged events (0)</h2>\" in html", "    assert \"0 event(s),\" in html", "    assert \"<h2>Unexpected entity loss (1)</h2>\" in html", "", "", "def test_a_degraded_report_still_lists_its_entity_loss_events() -> None:", "    \"\"\"Loss is deterministic, and the banner says the deterministic half is valid.", "", "    A degraded run has no grades at all, so every event falls through to the collapsed", "    section. That is precisely where a loss event must not be.", "    \"\"\"", "    lost = _ctx(E1, entity_loss_state=\"loss\", entity_check_status=\"not_run\")", "    keep = _ctx(E2, entity_loss_state=\"no_loss\", entity_check_status=\"not_run\")", "    html = render_report_html(_degraded_doc([lost, keep]))", "", "    assert \"<h2>Unexpected entity loss (1)</h2>\" in html", "    assert str(E1) not in _collapsed_section(html)", "    assert str(E2) in _collapsed_section(html)", "", "", "def test_a_run_with_no_entity_loss_says_so_rather_than_rendering_an_empty_section() -> None:", "    html = render_report_html(_doc([_ctx(E1)], grades=[_grade(E1)]))", "", "    assert \"<h2>Unexpected entity loss (0)</h2>\" in html", "    assert _cell(html, \"no-entity-loss\").startswith(\"No unexpected entity loss\")", "    assert \"<summary>Clean events (1)</summary>\" in html", "", "", "def test_the_not_assessed_linkage_headline_does_not_contradict_the_day_table() -> None:", "    \"\"\"The partial-day floor withholds a verdict on days that DO have events.", "", "    The old wording claimed no interval had any eligible event, which a reader could", "    read straight off the table below it and find false.", "    \"\"\"", "    html = render_report_html(", "        _doc(", "            [_ctx(E1)],", "            linkage_health=\"not_assessed\",", "            linkage_coverage=[_bucket(14, 5, 0, partial=True)],", "        )", "    )", "", "    assert \"no eligible events in any interval\" not in html", "    assert _cell(html, \"linkage-health\") == (", "        \"not assessed \u2014 no interval had enough eligible events to judge\"", "    )", "", "", "def test_a_loss_event_is_rendered_as_a_card_inside_its_own_section() -> None:", "    \"\"\"The heading is not the finding. The card under it is.\"\"\"", "    lost = _ctx(E1, title=\"Lost evidence\", entity_loss_state=\"loss\")", "    html = render_report_html(_doc([lost], grades=[_grade(E1)]))", "", "    assert str(E1) in _loss_section(html)", "    assert \"Lost evidence\" in _loss_section(html)", "", "", "def test_a_degraded_loss_event_is_rendered_as_a_card_too() -> None:", "    \"\"\"A degraded report has no grades at all, so the card is built from ``None``.", "", "    Pinned separately because this is the path a ``grade is not None`` guard would", "    silently drop, leaving the heading counting events the page never shows.", "    \"\"\"", "    lost = _ctx(E1, entity_loss_state=\"loss\", entity_check_status=\"not_run\")", "    html = render_report_html(_degraded_doc([lost]))", "", "    assert str(E1) in _loss_section(html)", "", "", "def test_a_loss_event_in_a_duplicate_pair_still_reaches_the_loss_section() -> None:", "    \"\"\"Pairing already removes an event from \"Clean events\" -- and would hide it here.", "", "    The two exclusions are independent: dropping the loss listing because the event", "    happened to be half of a pair would lose AC1's finding entirely.", "    \"\"\"", "    a, b = _ctx(E1, entity_loss_state=\"loss\"), _ctx(E2)", "    pair = QADuplicatePair(event_id_a=E1, event_id_b=E2, same_event=True, explanation=\"same event\")", "    html = render_report_html(", "        _doc([a, b], grades=[_grade(E1), _grade(E2)], pairs=[pair], duplicate_pair_count=1)", "    )", "", "    assert str(E1) in _loss_section(html)", "    assert str(E1) not in _collapsed_section(html)", "", "", "def test_a_not_assessed_event_is_neither_clean_nor_a_defect() -> None:", "    \"\"\"The envelope says ``not_assessed`` is folded into NEITHER count.", "", "    It was landing under \"Clean events\" regardless, which reports a verdict on evidence", "    that could not be read. It does not belong in the loss section either: an unresolved", "    contributor is an unknown, not a proven defect.", "    \"\"\"", "    unknown = _ctx(E1, entity_loss_state=\"not_assessed\")", "    sound = _ctx(E2, entity_loss_state=\"no_loss\")", "    html = render_report_html(_doc([unknown, sound], grades=[_grade(E1), _grade(E2)]))", "", "    assert str(E1) in _unassessed_section(html)", "    assert str(E1) not in _collapsed_section(html)", "    assert str(E1) not in _loss_section(html)", "    assert \"<h2>Unexpected entity loss (0)</h2>\" in html", "    # The control: a positively-assessed event still reaches \"Clean events\", so the", "    # exclusion above cannot be passing because the section is empty.", "    assert \"<summary>Clean events (1)</summary>\" in html", "    assert str(E2) in _collapsed_section(html)", "", "", "def test_a_thin_partial_day_holding_a_link_is_not_labelled_unjudged() -> None:", "    \"\"\"The row and its label have to agree (PR #495 human review, second comment).", "", "    A bucket at 2 of 2 rendered \"(partial, not judged)\" beside a 100% coverage cell,", "    because the floor was applied before the positive-link check.", "    \"\"\"", "    html = render_report_html(", "        _doc(", "            [_ctx(E1)], linkage_coverage=[_bucket(14, 2, 2, partial=True)], linkage_health=\"healthy\"", "        )", "    )", "", "    assert \"not judged\" not in _interval_table(html)", "    assert \"100.0%\" in _interval_table(html)"], "blocks": [{"start": 1, "end": 51, "label": "Imports and module setup"}, {"start": 52, "end": 65, "label": "def _row"}, {"start": 66, "end": 93, "label": "def _ctx"}, {"start": 94, "end": 109, "label": "def _entity_view"}, {"start": 110, "end": 131, "label": "def _metadata"}, {"start": 132, "end": 145, "label": "def _doc"}, {"start": 146, "end": 170, "label": "def test_grader_prompt_is_byte_identical_after_dat_8141"}, {"start": 171, "end": 189, "label": "def test_display_fields_are_absent_from_the_grader_row"}, {"start": 190, "end": 196, "label": "def test_script_payload_in_title_is_escaped"}, {"start": 197, "end": 219, "label": "def test_script_payload_in_llm_explanation_is_escaped"}, {"start": 220, "end": 229, "label": "def test_quote_payload_in_summary_is_escaped"}, {"start": 230, "end": 242, "label": "def test_null_title_renders_fallback_and_stays_null_in_json"}, {"start": 243, "end": 252, "label": "def test_partial_evidence_is_surfaced_when_docs_were_capped"}, {"start": 253, "end": 263, "label": "def test_no_partial_notice_when_all_documents_were_seen"}, {"start": 264, "end": 290, "label": "def test_flagged_event_appears_in_the_flagged_section_not_collapsed"}, {"start": 291, "end": 309, "label": "def test_duplicate_pair_renders_context_for_both_events"}, {"start": 310, "end": 323, "label": "def test_pair_naming_an_ungraded_event_is_skipped_not_half_rendered"}, {"start": 324, "end": 329, "label": "def test_page_is_self_contained"}, {"start": 330, "end": 378, "label": "def test_duplicate_pair_member_is_not_also_listed_as_clean"}, {"start": 379, "end": 431, "label": "def test_paired_but_not_flagged_event_shows_its_own_grade"}, {"start": 432, "end": 489, "label": "def test_flagged_and_paired_event_is_cross_listed_in_both_sections"}, {"start": 490, "end": 540, "label": "def test_pair_card_partial_evidence_can_cite_its_verdict"}, {"start": 541, "end": 561, "label": "def test_unpaired_clean_event_still_appears_in_clean"}, {"start": 562, "end": 575, "label": "def test_stylesheet_is_not_escaped_inside_the_style_element"}, {"start": 576, "end": 639, "label": "def test_flagged_heading_matches_the_count_the_cli_computes"}, {"start": 640, "end": 645, "label": "def _bucket"}, {"start": 646, "end": 651, "label": "def _interval_table"}, {"start": 652, "end": 658, "label": "def _cell"}, {"start": 659, "end": 668, "label": "def test_linkage_health_failed_is_visually_distinct_from_healthy"}, {"start": 669, "end": 676, "label": "def test_linkage_health_not_assessed_reads_as_neither"}, {"start": 677, "end": 686, "label": "def test_interval_table_renders_a_row_per_bucket_with_a_computed_percentage"}, {"start": 687, "end": 699, "label": "def test_an_empty_interval_renders_as_not_assessed_never_as_zero_percent"}, {"start": 700, "end": 706, "label": "def test_a_zero_link_interval_with_events_does_render_zero_percent_and_is_marked"}, {"start": 707, "end": 712, "label": "def test_partial_buckets_are_labelled_rather_than_dropped"}, {"start": 713, "end": 723, "label": "def test_interval_table_scrolls_inside_its_own_container"}, {"start": 724, "end": 729, "label": "def test_sampled_zero_link_count_is_labelled_about_the_graded_sample"}, {"start": 730, "end": 737, "label": "def test_unexpected_entity_loss_count_and_the_dropped_gap_are_both_rendered"}, {"start": 738, "end": 749, "label": "def test_unmeasured_counts_say_so_rather_than_rendering_zero"}, {"start": 750, "end": 754, "label": "def test_per_event_pre_trim_direct_link_count_is_shown_beside_the_document_count"}, {"start": 755, "end": 761, "label": "def test_per_event_entity_loss_state_renders_all_three_states"}, {"start": 762, "end": 772, "label": "def test_the_page_states_what_the_measure_does_and_does_not_mean"}, {"start": 773, "end": 784, "label": "def test_linkage_rendering_keeps_the_page_self_contained"}, {"start": 785, "end": 810, "label": "def test_complete_event_renders_its_entities_by_name_and_type"}, {"start": 811, "end": 826, "label": "def test_partial_event_names_the_specific_cause"}, {"start": 827, "end": 835, "label": "def test_partial_status_has_its_own_class_so_it_cannot_be_skimmed_past"}, {"start": 836, "end": 863, "label": "def test_not_run_distinguishes_no_links_from_all_evidence_removed"}, {"start": 864, "end": 883, "label": "def test_a_truncated_name_carries_a_trailing_ellipsis"}, {"start": 884, "end": 900, "label": "def test_entity_name_from_scraped_text_is_escaped"}, {"start": 901, "end": 920, "label": "def _grade"}, {"start": 921, "end": 928, "label": "def test_a_plausible_verdict_renders_as_plausible_and_does_not_flag"}, {"start": 929, "end": 950, "label": "def test_an_implausible_verdict_renders_its_explanation_and_reaches_the_flagged_section"}, {"start": 951, "end": 961, "label": "def test_a_null_verdict_renders_as_not_applicable_naming_no_links"}, {"start": 962, "end": 973, "label": "def test_a_null_verdict_names_evidence_removed_when_that_is_why"}, {"start": 974, "end": 998, "label": "def test_the_flagged_section_names_which_check_flagged_each_event"}, {"start": 999, "end": 1019, "label": "def test_existing_flag_reasons_render_exactly_as_before"}, {"start": 1020, "end": 1033, "label": "def test_the_linkage_explanation_is_escaped"}, {"start": 1034, "end": 1051, "label": "def _degraded_doc"}, {"start": 1052, "end": 1078, "label": "def test_a_degraded_report_makes_no_affirmative_clean_claim"}, {"start": 1079, "end": 1094, "label": "def test_a_complete_report_keeps_its_clean_language"}, {"start": 1095, "end": 1119, "label": "def test_a_degraded_report_does_not_explain_why_entities_are_missing"}, {"start": 1120, "end": 1148, "label": "def test_a_degraded_document_cannot_claim_a_completed_entity_check"}, {"start": 1149, "end": 1159, "label": "def _collapsed_section"}, {"start": 1160, "end": 1165, "label": "def _unassessed_section"}, {"start": 1166, "end": 1177, "label": "def _loss_section"}, {"start": 1178, "end": 1197, "label": "def test_an_entity_loss_event_does_not_land_under_clean_events"}, {"start": 1198, "end": 1212, "label": "def test_an_entity_loss_event_that_is_also_flagged_appears_in_both_sections"}, {"start": 1213, "end": 1226, "label": "def test_the_flagged_count_in_the_meta_table_is_unmoved_by_entity_loss"}, {"start": 1227, "end": 1241, "label": "def test_a_degraded_report_still_lists_its_entity_loss_events"}, {"start": 1242, "end": 1249, "label": "def test_a_run_with_no_entity_loss_says_so_rather_than_rendering_an_empty_section"}, {"start": 1250, "end": 1269, "label": "def test_the_not_assessed_linkage_headline_does_not_contradict_the_day_table"}, {"start": 1270, "end": 1278, "label": "def test_a_loss_event_is_rendered_as_a_card_inside_its_own_section"}, {"start": 1279, "end": 1290, "label": "def test_a_degraded_loss_event_is_rendered_as_a_card_too"}, {"start": 1291, "end": 1306, "label": "def test_a_loss_event_in_a_duplicate_pair_still_reaches_the_loss_section"}, {"start": 1307, "end": 1327, "label": "def test_a_not_assessed_event_is_neither_clean_nor_a_defect"}, {"start": 1328, "end": 1341, "label": "def test_a_thin_partial_day_holding_a_link_is_not_labelled_unjudged"}], "lineCount": 1341, "sha256": "f522d6cd63577e637330483fab03e8271e86e4d5009bd00b9b36eaecbdf27a5b", "endsWithNewline": true});
